do $$ declare t text; begin
  foreach t in array array['ecc_entity_settings','ecc_brand_kits','ecc_sending_domains','ecc_templates','ecc_lists','ecc_segments','ecc_consent_records','ecc_suppressions','ecc_campaigns','ecc_sends','ecc_send_jobs','ecc_send_messages','ecc_campaign_recipients','ecc_engagement_events','ecc_journeys','ecc_journey_enrollments','ecc_dialer_attempts','ecc_conversation_state','ecc_audit_log','ecc_command_center_cache'] loop
    execute format('alter table public.%I enable row level security', t);
    begin execute format('create policy %I on public.%I for select to authenticated using (public.is_firm_wide_access() or public.can_access_entity(entity_id))', t||'_select', t);
    exception when others then null; end;
  end loop;
end $$;
